// Each job remembers its own normal-attack and ultimate configuration.
const NORMAL_TECHNIQUES=[{name:'標準',sp:1,time:1,power:1},{name:'速攻',sp:.75,time:.8,power:.75},{name:'強撃',sp:1.5,time:1.3,power:1.5}];
function combatTechnique(){return p?.combatTechniques?.[currentJob()]||{normal:0,ultimate:0};}
configuredUltimateCost=()=>combatTechnique().ultimate===1?60:100;
configuredCompactUltimate=()=>combatTechnique().ultimate===1;
const techniqueSaveBase=validateSave;validateSave=data=>{const out=techniqueSaveBase(data),src=data.p.combatTechniques;if(src!==undefined){if(!src||typeof src!=='object'||Array.isArray(src))throw Error('技の設定が不正です');out.p.combatTechniques={};for(const [key,value]of Object.entries(src)){if(!/^(?:[0-9]|1[0-5])$/.test(key)||!value||![0,1,2].includes(value.normal)||![0,1].includes(value.ultimate))throw Error('技の設定が不正です');out.p.combatTechniques[key]={normal:value.normal,ultimate:value.ultimate};}}return out;};
function chooseCombatTechnique(kind,index){if(!paused||!started||dead||!['normal','ultimate'].includes(kind)||!Number.isInteger(index)||index<0||index>(kind==='normal'?2:1))return false;const old=p.combatTechniques;p.combatTechniques={...old,[currentJob()]:{...combatTechnique(),[kind]:index}};if(save()===false){if(old===undefined)delete p.combatTechniques;else p.combatTechniques=old;say('保存できなかったため変更を戻しました');return false;}panel('gems');iconSelectEntry(kind==='normal'?'normal-attack':'ultimate');return true;}
const techniqueCostBase=staminaCost;staminaCost=n=>techniqueCostBase(n)*(n===0?NORMAL_TECHNIQUES[combatTechnique().normal].sp:1);
const techniqueCastBase=cast;cast=n=>{const before=playerAction,result=techniqueCastBase(n);if(n===0&&playerAction&&playerAction!==before){const index=combatTechnique().normal,t=NORMAL_TECHNIQUES[index];playerAction.technique=index;playerAction.duration*=t.time;playerAction.impact*=t.time;cd[0]*=t.time;}return result;};
let techniqueImpact=null;const techniquePerformBase=performAction;performAction=action=>{const old=techniqueImpact;techniqueImpact=action.n===0?(action.technique??combatTechnique().normal):null;try{return techniquePerformBase(action);}finally{techniqueImpact=old;}};
const techniqueHitBase=hit;hit=(e,d)=>techniqueHitBase(e,d*(classHitKind==='normal'&&!e?.dotTick&&!treeExplosion?NORMAL_TECHNIQUES[techniqueImpact??combatTechnique().normal].power:1));
function combatLoadoutEntries(){const job=profession(),selected=combatTechnique(),normal=NORMAL_TECHNIQUES[selected.normal],summoner=combatProfessionType()>=6;return [{key:'normal-attack',label:'通常攻撃：'+normal.name,icon:menuIcon('weapon'),nodes:[loadoutNode('<p>'+gearEscape(job.name)+'</p>'+jobGuideContent('basic',currentJob())+'<p>SP '+staminaCost(0).toFixed(1)+' ／ 動作時間 '+Math.round(normal.time*100)+'% ／ 直撃威力 '+Math.round(normal.power*100)+'%</p>'+(summoner?'<p>召喚・指示のSPと動作時間に適用。仲間の自動攻撃の威力は変わりません。</p>':'')),...NORMAL_TECHNIQUES.map((t,i)=>loadoutAction((i===selected.normal?'✓ ':'')+t.name+'：SP '+Math.round(t.sp*100)+'%・時間 '+Math.round(t.time*100)+'%・直撃 '+Math.round(t.power*100)+'%',()=>chooseCombatTechnique('normal',i)))]},{key:'ultimate',label:'必殺技：'+job.ultimate,icon:menuIcon('skills'),nodes:[loadoutNode('<h3>'+gearEscape(job.ultimate)+'</h3><p>'+gearEscape(job.desc)+'</p><p>通常型：ゲージ100。短縮型：ゲージ60で、打撃回数または持続時間を約半分にします（端数切り上げ）。1発の威力は同じです。</p>'),...['通常型 · ゲージ100','短縮型 · ゲージ60'].map((name,i)=>loadoutAction((i===selected.ultimate?'✓ ':'')+name,()=>chooseCombatTechnique('ultimate',i)))]}];}
